{"path": "/启动Biblioshiny.bat", "content": "@echo off
title Biblioshiny - 文献计量分析
color 0A

echo ============================================
echo    Biblioshiny - 文献计量可视化分析
echo ============================================
echo.

set RSCRIPT=C:\Program Files\R\R-4.6.0\bin\x64\Rscript.exe
set R_SCRIPT=%USERPROFILE%\Desktop\launch_biblioshiny.R

if not exist "%RSCRIPT%" (
    echo [失败] 找不到 Rscript.exe
    echo 预期路径: %RSCRIPT%
    pause
    exit /b 1
)

echo [信息] 正在写入 R 启动脚本...

REM 生成 R 脚本文件
(
echo # Biblioshiny 启动脚本
echo .libPaths^(c^("~/R/win-library/4.6", .libPaths^(^)^)^)
echo library^(bibliometrix^)
echo cat^("启动 Biblioshiny...\n"^)
echo biblioshiny^(^)
) > "%R_SCRIPT%"

echo [信息] R 启动脚本已生成
echo [信息] 正在启动 Biblioshiny...
echo.
echo 如果浏览器没有自动打开，请手动复制命令行中的地址
echo 到浏览器访问（如 http://127.0.0.1:xxxx）
echo.
echo ============================================
echo 正在运行，关闭此窗口即退出
echo ============================================

"%RSCRIPT%" "%R_SCRIPT%"

echo.
echo ============================================
echo [完成] Biblioshiny 已停止
pause
"}

